CREATE TABLE IF NOT EXISTS cij_norms(code text PRIMARY KEY,title text NOT NULL,source_url text NOT NULL,enabled boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS cij_versions(id uuid PRIMARY KEY,norm_code text NOT NULL REFERENCES cij_norms(code),digest text NOT NULL,source_url text NOT NULL,retrieved_at timestamptz NOT NULL,method text NOT NULL,raw_html text NOT NULL,full_text text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','invalid')),warnings jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz,reviewed_by uuid REFERENCES users(id),review_note text,UNIQUE(norm_code,digest));
CREATE TABLE IF NOT EXISTS cij_articles(id uuid PRIMARY KEY,version_id uuid NOT NULL REFERENCES cij_versions(id),number text NOT NULL,ordinal integer NOT NULL,path jsonb NOT NULL,blocks jsonb NOT NULL,body text NOT NULL,search tsvector GENERATED ALWAYS AS(to_tsvector('portuguese',body)) STORED,UNIQUE(version_id,ordinal));
CREATE INDEX IF NOT EXISTS cij_articles_search ON cij_articles USING gin(search);
CREATE INDEX IF NOT EXISTS cij_articles_number ON cij_articles(number,version_id);
CREATE INDEX IF NOT EXISTS cij_versions_norm ON cij_versions(norm_code,created_at DESC);
CREATE TABLE IF NOT EXISTS cij_relationships(id uuid PRIMARY KEY,norm_code text REFERENCES cij_norms(code),article_number text NOT NULL,nature_code text NOT NULL,verified boolean NOT NULL DEFAULT false,note text NOT NULL,actor_id uuid REFERENCES users(id),updated_at timestamptz DEFAULT now(),UNIQUE(norm_code,article_number,nature_code));
CREATE TABLE IF NOT EXISTS cij_bookmarks(user_id uuid REFERENCES users(id) ON DELETE CASCADE,article_id uuid REFERENCES cij_articles(id),favorite boolean DEFAULT false,visited_at timestamptz DEFAULT now(),PRIMARY KEY(user_id,article_id));
CREATE TABLE IF NOT EXISTS cij_audit(id uuid PRIMARY KEY,actor_id uuid REFERENCES users(id),action text NOT NULL,version_id uuid REFERENCES cij_versions(id),detail text NOT NULL,created_at timestamptz DEFAULT now());
